import {RECORDS,RECORD_GENRES} from './records.js';

export function recordsMarkup(s,filter='TODOS',previewId=null){
 const active=s.records.active,shown=RECORDS.filter(r=>filter==='TODOS'||r.genre===filter);
 const fmt=n=>new Intl.NumberFormat('pt-BR').format(n);
 return `<div class="records-head"><div class="gramophone-scene" aria-hidden="true"><div class="gramophone-horn"></div><div class="gramophone-neck"></div><div class="gramophone-disc"><i></i></div><div class="gramophone-box"></div><span>♫</span></div><div><span class="eyebrow">${s.records.owned.length} / ${RECORDS.length} DISCOS</span><h2>VITROLA</h2><strong>✦ ${fmt(s.essence)} ESSÊNCIAS</strong></div></div><nav class="record-filters" aria-label="Filtrar gêneros">${RECORD_GENRES.map(g=>`<button data-record-filter="${g}" class="${filter===g?'selected':''}" aria-pressed="${filter===g}">${g}</button>`).join('')}</nav><div class="record-grid">${shown.map(r=>{const owned=s.records.owned.includes(r.id),playing=active===r.id,previewing=previewId===r.id;return `<article class="record-card ${playing?'playing':''} ${previewing?'previewing':''}" style="--record:${r.color}"><div class="record-cover" aria-hidden="true"><i></i><b>♫</b></div><div class="record-copy"><small>${r.genre}</small><h3>${r.name}</h3><span>${owned?'NA COLEÇÃO':r.source+' · ✦ '+fmt(r.cost)}</span></div><div class="record-actions"><button type="button" class="record-preview" data-record-preview="${r.id}" aria-pressed="${previewing}" aria-label="${previewing?'Parar prévia':'Ouvir 5 segundos de'} ${r.name}">${previewing?'■ PARAR':'▶ OUVIR 5s'}<i class="record-preview-meter" aria-hidden="true"></i></button><button type="button" data-record="${r.id}" ${playing||!owned&&s.essence<r.cost?'disabled':''}>${playing?'TOCANDO':owned?'TOCAR':'COMPRAR'}</button></div></article>`;}).join('')}</div>`;
}
